<?php require __DIR__.'/php/bootstrap.php'; $id=$_SESSION['user_id']??null; if($id) log_event('LOGOUT',null,(int)$id); $_SESSION=[]; if(ini_get('session.use_cookies')) { $p=session_get_cookie_params(); setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',(bool)$p['secure'],(bool)$p['httponly']); } session_destroy(); header('Cache-Control: no-store, no-cache, must-revalidate'); header('Location: index.php'); exit; ?>
